// @ts-ignore generated by `opennextjs-cloudflare build`
import handler from './.open-next/worker.js'
import { runCronJobs } from './cron-triggers'

type Env = { CRON_SECRET?: string }
type Ctx = { waitUntil(promise: Promise<unknown>): void }

export default {
  fetch: handler.fetch,
  scheduled(event: { cron: string }, env: Env, ctx: Ctx) {
    ctx.waitUntil(runCronJobs(event.cron, env.CRON_SECRET, (request) => handler.fetch(request, env, ctx)))
  },
}
